def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_live = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > budget:
                rich_live += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 17.0
    ample_supply = supply >= 22.0
    urgent = hp <= 3 or no_water >= 2
    semi_urgent = hp <= 5 or no_water >= 1

    if urgent:
        bid = DAILY_SALARY * 1.18
    elif semi_urgent:
        bid = DAILY_SALARY * 0.92
    else:
        if highest_prev >= 135.0:
            bid = DAILY_SALARY * (0.28 if ample_supply else 0.42)
        elif highest_prev >= 90.0:
            bid = DAILY_SALARY * (0.38 if ample_supply else 0.58)
        else:
            bid = max(DAILY_SALARY * 0.45, avg_prev + 2.0)

    if tight_supply:
        bid += 10.0
    elif ample_supply:
        bid -= 6.0

    if day >= 8:
        bid += 8.0
    if day >= 9 and semi_urgent:
        bid += 10.0

    if rich_live >= 2 and not semi_urgent:
        bid -= 5.0

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 1.2
    elif day == 8:
        reserve = DAILY_SALARY * 0.7
    elif day == 9:
        reserve = DAILY_SALARY * 0.3

    max_affordable = max(0.0, budget - reserve)
    if urgent:
        max_affordable = budget

    bid = max(0.0, min(bid, max_affordable if max_affordable > 0 else budget))

    if bid < 1.0 and budget >= 1.0 and semi_urgent:
        bid = min(budget, 1.0)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    clearing_hint = 0.0
    if prev_bids:
        clearing_hint = max(prev_bids)

    # If opponents were bidding extremely high, we must compete; otherwise bid moderately.
    # Target: slightly above the likely max previous bid, but capped by budget.
    # Use supply to decide aggressiveness: higher supply reduces need to overpay.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Base pressure factor from my health/no-water streak
    hp_factor = 1.0
    if my_hp <= 2.0:
        hp_factor = 1.25
    elif my_hp <= 4.0:
        hp_factor = 1.15
    elif my_hp >= 8.0:
        hp_factor = 0.95

    no_water_factor = 1.0
    if my_no_water_days >= 2:
        no_water_factor = 1.2
    elif my_no_water_days >= 3:
        no_water_factor = 1.35

    # Aggression level based on yesterday's max bid
    # Cindy averaged ~150; if we see near that, we bid near but not equal to avoid waste.
    if clearing_hint >= 0.95 * 150.0:
        target = 145.0
    elif clearing_hint >= 120.0:
        target = clearing_hint + 3.0
    elif clearing_hint >= 60.0:
        target = max(DAILY_SALARY * 0.65, clearing_hint + 2.0)
    else:
        target = DAILY_SALARY * (0.55 + 0.25 * (1.0 - supply_ratio))

    # Adjust for supply: when supply is high, reduce target
    target *= (1.0 - 0.25 * supply_ratio)

    target *= hp_factor
    target *= no_water_factor

    # Ensure we can afford it; also keep minimum useful bid
    # If budget is very low, still try to buy water if we're at risk.
    if my_budget <= 0.0:
        return 0.0

    # Cap by budget and a reasonable upper bound (avoid irrational bids)
    cap = my_budget
    # If we're healthy, avoid spending everything
    if my_hp >= 7.0 and my_no_water_days <= 1:
        cap = min(cap, DAILY_SALARY * 0.9)

    bid = min(cap, target)

    # If bid becomes too small relative to WATER_REQ pressure, raise slightly
    # (We don't know exact conversion, so use a safe floor tied to DAILY_SALARY)
    if bid < DAILY_SALARY * 0.35 and (my_hp <= 4.0 or my_no_water_days >= 2):
        bid = min(cap, DAILY_SALARY * 0.6)

    if bid < 0.0:
        bid = 0.0
    return float(bid)

